window.listOfSelect=window.listOfSelect||[];function findSelect(inputId){return listOfSelect.find(select=>select.id==="roro-wrapper-"+inputId)}window.roroAddOption=function(inputId,key,value,categoryLabel=null){const select=findSelect(inputId);select&&select.ready.then(()=>{const option=new Option(key,null,value);option.ready.then(()=>select.addOption(option,categoryLabel))})},window.roroDisableSelect=function(inputId,disable=!0){const select=findSelect(inputId);select&&select.ready.then(()=>select.disable(disable))},window.roroReadonlySelect=function(inputId,readonly=!0){const select=findSelect(inputId);select&&select.ready.then(()=>select.readonly(readonly))},window.roroShowDropDown=function(inputId,show=!0){const select=findSelect(inputId);select&&select.ready.then(()=>select.showDropDown(show))},window.addSelect=function(elt){listOfSelect.push(new RoroSelect(elt.data("id"),elt.data("options"),elt.data("value")))},window.addMultiSelect=function(elt){listOfSelect.push(new RoroMultiSelect(elt.data("id"),elt.data("name"),elt.data("options"),elt.data("values")))},$(document).ready(function(){$(".roro-wrapper-select").each(function(){addSelect($(this))}),$(".roro-wrapper-multi-select").each(function(){addMultiSelect($(this))})});
